UPDATE video_status_consumed_event
SET consumer_retry_count = GREATEST(
        consumer_retry_count,
        #{attempt}
    ),
    last_attempt_at = NOW(3),
    last_error = #{lastError}
WHERE event_id = #{eventId}
  AND process_status = 0

UPDATE video_status_consumed_event
SET process_status = 3,
    last_attempt_at = NOW(3),
    last_error = #{lastError}
WHERE event_id = #{eventId}
  AND process_status = #{expectedStatus}

UPDATE video_status_consumed_event
SET last_attempt_at = NOW(3),
    last_error = #{resolution}
WHERE event_id = #{eventId}
  AND process_status = 3

mapper.select:
SELECT

FROM video_status_consumed_event
WHERE process_status = 3

    AND id > #{afterId}

ORDER BY id
LIMIT #{limit}

SELECT DISTINCT vid
FROM video_status_consumed_event
WHERE process_status = 1

    AND vid > #{afterVid}

ORDER BY vid
LIMIT #{limit}

SELECT id, event_id, vid, event_type, delta, payload_hash, payload, process_status, consumer_retry_count, last_attempt_at, last_error, consumed_at, redis_applied_at, flushed_at, compensation_attempts, compensation_next_attempt_at, compensation_lease_token, compensation_lease_until, last_compensation_at, TIMESTAMPDIFF(SECOND, consumed_at, NOW(3)) AS consumed_age_seconds, NOW(3) AS db_now FROM video_status_consumed_event WHERE process_status = 0 AND last_attempt_at < DATE_SUB(NOW(3), INTERVAL #{minAgeSeconds} SECOND) AND TIMESTAMPDIFF(SECOND, consumed_at, NOW(3)) >= 0 AND TIMESTAMPDIFF(SECOND, consumed_at, NOW(3)) < #{maxAgeSeconds} AND (compensation_next_attempt_at IS NULL OR compensation_next_attempt_at <= NOW(3)) AND (compensation_lease_until IS NULL OR compensation_lease_until <= NOW(3)) AND compensation_attempts < #{maxAttempts}
AND id > #{afterId}
ORDER BY id LIMIT #{limit}

SELECT id, event_id, vid, event_type, delta, payload_hash, process_status, consumer_retry_count, last_attempt_at, last_error, consumed_at, compensation_attempts, compensation_next_attempt_at, compensation_lease_token, compensation_lease_until, last_compensation_at, TIMESTAMPDIFF(SECOND, consumed_at, NOW(3)) AS consumed_age_seconds, NOW(3) AS db_now FROM video_status_consumed_event WHERE process_status = 0
AND id > #{afterId}
ORDER BY id LIMIT #{limit}

SELECT COUNT(*)
FROM (
    SELECT 1
    FROM video_status_consumed_event
    WHERE process_status = 0
      AND TIMESTAMPDIFF(SECOND, consumed_at, NOW(3)) >= #{maxAgeSeconds}
    LIMIT #{cap}
) bounded

