UPDATE video_status_consumed_event
SET compensation_lease_token = NULL,
    compensation_lease_until = NULL,
    compensation_next_attempt_at = DATE_ADD(NOW(3), INTERVAL #{cooldownSeconds} SECOND),
    last_error = #{lastError}
WHERE event_id = #{eventId}
  AND process_status = 0
  AND compensation_lease_token = #{leaseToken}
